						+ "<" + SUBJECT + "> <" + SERVICE_PREDICATE + "> ?endpoint . "
						+ "SERVICE ?endpoint { <urn:rdf4j:lmdb-service-replay:remote> "
						+ "<urn:rdf4j:lmdb-service-replay:remote-value> ?remoteValue } }";
