	private static void awaitReplayAccepted(LongSupplier replayAccepted, long initialReplayAccepted,
			Supplier<String> growthMetrics) {
		long deadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (replayAccepted.getAsLong() <= initialReplayAccepted) {
			if (System.nanoTime() >= deadlineNanos) {
				AssertionError failure = new AssertionError(
						"the soft growth episode did not accept the blocked SERVICE query for replay");
				printGrowthFailureDiagnostic("SERVICE replay acceptance deadline expired", failure, growthMetrics);
				throw failure;
			}
			Thread.onSpinWait();
		}
	}

	private static void printGrowthFailureDiagnostic(String label, Throwable failure, Supplier<String> growthMetrics) {
		System.err.println("LMDB service replay diagnostic: " + label);
		System.err.println("Growth metrics: " + growthMetrics.get());
		failure.printStackTrace(System.err);
		ThreadMXBean threadMXBean = ManagementFactory.getThreadMXBean();
		long[] deadlockedIds = threadMXBean.findDeadlockedThreads();
		System.err
				.println("Deadlocked thread ids: " + (deadlockedIds == null ? "none" : Arrays.toString(deadlockedIds)));
		for (ThreadInfo threadInfo : threadMXBean.dumpAllThreads(true, true)) {
			if (threadInfo == null) {
				continue;
			}
			System.err.println("Thread \"" + threadInfo.getThreadName() + "\" id=" + threadInfo.getThreadId()
					+ " state=" + threadInfo.getThreadState() + " lock=" + threadInfo.getLockName()
					+ " lockOwner=" + threadInfo.getLockOwnerName() + " lockOwnerId=" + threadInfo.getLockOwnerId());
			for (StackTraceElement frame : threadInfo.getStackTrace()) {
				System.err.println("\tat " + frame);
			}
			for (var monitor : threadInfo.getLockedMonitors()) {
				System.err.println("\tlocked monitor=" + monitor);
			}
			for (var synchronizer : threadInfo.getLockedSynchronizers()) {
				System.err.println("\tlocked synchronizer=" + synchronizer);
			}
		}
	}

	private static Model growthStatements(int count) {
		Model statements = new LinkedHashModel();
		for (int i = 0; i < count; i++) {
			statements.add(Values.iri("urn:rdf4j:lmdb-service-replay:growth:" + i), GROWTH_PREDICATE,
					Values.literal("growth"));
		}
		return statements;
	}

	private static final class ServiceGate implements AutoCloseable {

		private static final byte[] RESULTS = ("<?xml version=\"1.0\" encoding=\"UTF-8\"?>"
				+ "<sparql xmlns=\"http://www.w3.org/2005/sparql-results#\"><head>"
				+ "<variable name=\"remoteValue\"/></head><results><result>"
				+ "<binding name=\"remoteValue\"><literal>service-result</literal></binding>"
				+ "</result></results></sparql>").getBytes(StandardCharsets.UTF_8);

		private final CountDownLatch firstRequest = new CountDownLatch(1);
		private final CountDownLatch release = new CountDownLatch(1);
		private final AtomicInteger requestCount = new AtomicInteger();
		private final ExecutorService executor = Executors.newCachedThreadPool();
		private final HttpServer httpServer;

		private ServiceGate() throws IOException {
			httpServer = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
			httpServer.setExecutor(executor);
			httpServer.createContext("/sparql", this::handle);
			httpServer.start();
		}

		private String endpoint() {
			return "http://127.0.0.1:" + httpServer.getAddress().getPort() + "/sparql";
		}

		private boolean awaitFirstRequest() throws InterruptedException {
			return firstRequest.await(10, TimeUnit.SECONDS);
		}

		private int requestCount() {
			return requestCount.get();
		}

		private void release() {
			release.countDown();
		}

		private void handle(HttpExchange exchange) throws IOException {
			requestCount.incrementAndGet();
			firstRequest.countDown();
			try {
				if (!release.await(60, TimeUnit.SECONDS)) {
					exchange.sendResponseHeaders(503, -1);
					return;
				}
				exchange.getResponseHeaders().set("Content-Type", "application/sparql-results+xml; charset=UTF-8");
				exchange.sendResponseHeaders(200, RESULTS.length);
				exchange.getResponseBody().write(RESULTS);
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				exchange.sendResponseHeaders(503, -1);
			} finally {
				exchange.close();
			}
		}

		@Override
		public void close() {
			release();
			httpServer.stop(0);
			executor.shutdownNow();
		}
	}
